            rows.forEach(System.out::println);
        } catch (SQLException e) {
            System.err.println("Database error [SQLState " + e.getSQLState() + ", code "
                    + e.getErrorCode() + "]: " + e.getMessage());
            System.exit(1);
        }
    }
}
